from pathlib import Path
import re, sys
root=Path('.')
files=[Path('README.md'), Path('AGENTS.md')] + sorted(Path('docs').rglob('*.md')) + [Path('privileged-helper/README.md')]
missing=[]
for p in files:
    text=p.read_text(encoding='utf-8')
    for target in re.findall(r'\[[^\]]*\]\(([^)]+)\)', text):
        if '://' in target or target.startswith('#') or target.startswith('mailto:'):
            continue
        target=target.split('#',1)[0]
        if not target:
            continue
        q=(p.parent/target).resolve()
        try:
            q.relative_to(root.resolve())
        except ValueError:
            continue
        if not q.exists():
            missing.append((str(p),target))
if missing:
    print('BROKEN_RELATIVE_LINKS')
    for x in missing: print(x)
    sys.exit(1)
print('MARKDOWN_RELATIVE_LINKS_OK', len(files))
